const it = [10, 20][Symbol.iterator]();
it.next(); // { value: 10, done: false }
it.next(); // { value: 20, done: false }
it.next(); // { value: undefined, done: true }

function* range(from, to) {
  for (let n = from; n <= to; n++) yield n;
}
for (const n of range(1, 3)) console.log(n); // 1 2 3

function* squares() { let n = 1; while (true) yield n * n++; }
const g = squares();
g.next().value; // 1  (only one square computed so far)

function* naturals() { let n = 1; while (true) yield n++; }
const it = naturals();
[it.next().value, it.next().value]; // [1, 2]

function* inner() { yield 1; yield 2; }
function* outer() { yield 0; yield* inner(); yield 3; }
[...outer()]; // [0, 1, 2, 3]

function* idGen() { let id = 0; while (true) yield ++id; }
const nextId = idGen();
nextId.next().value; // 1

