const range = {
  from: 1,
  to: 4,
  [Symbol.iterator]() {
    let n = this.from;
    const to = this.to;
    return {
      next() {
        return n <= to
          ? { value: n++, done: false }
          : { value: undefined, done: true };
      }
    };
  }
};

for (const n of range) console.log(n);
console.log([...range]);

function* naturals() {
  let n = 1;
  while (true) yield n++;
}

function take(iterable, count) {
  const out = [];
  for (const x of iterable) {
    out.push(x);
    if (out.length === count) break;
  }
  return out;
}

console.log(take(naturals(), 5)); // [1,2,3,4,5]

function* squares(nums) {
  for (const n of nums) yield n * n;
}
console.log([...squares([1, 2, 3])]); // [1,4,9]

