solution.code:
function* range(from, to) {
  for (let n = from; n <= to; n++) {
    yield n;
  }
}

for (const n of range(1, 3)) console.log(n); // 1 2 3

function* fib() {
  let a = 0, b = 1;
  while (true) {
    yield a;
    [a, b] = [b, a + b];
  }
}

function take(iterable, n) {
  const out = [];
  for (const x of iterable) {
    if (out.length >= n) break;
    out.push(x);
  }
  return out;
}

console.log(take(fib(), 8)); // [0,1,1,2,3,5,8,13]
